// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/family.ts, then fixed by hand where it says so.
// Ages, children and growing up.
//
// Everyone has an age (years). A year passes every YEAR_DAYS (a full round of
// seasons); from ELDER on, people work at 3/4 speed. In a harsh game, two
// adults who think the world of each other (LOVERS both ways) may have a
// baby, once a day at most for the colony, if there's a spare bed for it (a
// hash roll, not the sim RNG). Children don't work (no priorities) and grow
// up after CHILDHOOD ticks, with a head start in a couple of skills.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Family
{
    static Family()
    {
        Time.onClock(() => CHILDHOOD = 10 * Time.DAY_LENGTH);
    }

    public const int YEAR_DAYS = 20;

    public const int ELDER = 65;

    public const int LOVERS = 60;

    public const double BIRTH_CHANCE = 0.25;

    public const int MAX_PARENT_AGE = 50;

    public static double CHILDHOOD = 10 * Time.DAY_LENGTH;

    /// <summary>Age a child is counted as once grown.</summary>
    public const int GROWN_AGE = 16;

    public static readonly List<string> HEAD_START = ["build", "farm", "craft", "cook", "doctor", "guard", "scavenge"];

    public static bool isChild(Survivor s)
    {
        return s.childUntil != null;
    }

    public static bool isElder(Survivor s)
    {
        return s.age >= ELDER;
    }

    /// <summary>An adult's starting age, from their id.</summary>
    public static double startingAge(string id)
    {
        return 18 + JsMath.floor(Hash.hashRoll(Hash.idNumber(id), 2718.0) * 45);
    }

    public static void updateFamily(SimState state)
    {
        if ((state.tick > 0) && ((state.tick % (YEAR_DAYS * Time.DAY_LENGTH)) == 0))
        {
            foreach (var s in Js.Iter(state.survivors))
            {
                s.age += 1;
            }
        }
        foreach (var s in Js.Iter(state.survivors))
        {
            if ((s.childUntil != null) && (state.tick >= s.childUntil))
            {
                growUp(state, s);
            }
        }
        if (Js.T(state.harsh) && ((state.tick % Time.DAY_LENGTH) == ((double)(Time.DAY_LENGTH) / (2))))
        {
            births(state);
        }
    }

    public static void births(SimState state)
    {
        var spareBed = FurnitureMod.ofKind(state, "bed").some((f) => f.owner == null);
        if (!spareBed)
        {
            return;
        }
        var adults = state.survivors.filter((s) => !isChild(s) && (s.age <= MAX_PARENT_AGE));
        for (var i = 0; i < adults.length; i++)
        {
            for (var j = i + 1; j < adults.length; j++)
            {
                var a = Js.NN(Js.Get(adults, i));
                var b = Js.NN(Js.Get(adults, j));
                if ((Relationships.opinion(a, b) < LOVERS) || (Relationships.opinion(b, a) < LOVERS))
                {
                    continue;
                }
                if (Hash.hashRoll(Hash.idNumber(a.id), Hash.idNumber(b.id), state.tick) >= BIRTH_CHANCE)
                {
                    continue;
                }
                var spot = Space.nearestTile(state.grid, a.pos, (x, y) => Grids.isWalkable(state.grid, x, y)) ?? a.pos;
                var baby = Survivors.addSurvivor(state, spot.x, spot.y);
                baby.age = 0;
                baby.childUntil = state.tick + CHILDHOOD;
                baby.priorities = new(JobTypes.NO_JOBS) {  };
                baby.opinions = new() { [Js.Str(a.id)] = 50, [Js.Str(b.id)] = 50 };
                a.opinions[Js.Idx(baby.id)] = 50;
                b.opinions[Js.Idx(baby.id)] = 50;
                Events.logEvent(state, $"A baby, {Js.Str(baby.name)}, was born to {Js.Str(a.name)} and {Js.Str(b.name)}");
                return;
            }
        }
    }

    public static void growUp(SimState state, Survivor s)
    {
        s.childUntil = null;
        s.age = JsMath.max(s.age, GROWN_AGE);
        s.priorities = new(JobTypes.DEFAULT_PRIORITIES) {  };
        var n = Hash.idNumber(s.id);
        var a = Js.NN(Js.Get(HEAD_START, n % HEAD_START.length));
        var b = Js.NN(Js.Get(HEAD_START, (n + 3) % HEAD_START.length));
        foreach (var t in Js.Iter((List<string>)[a, b]))
        {
            s.xp[Js.Idx(t)] = (Js.Q(Js.Get(s.xp, t), 0)) + (2 * Skills.XP_PER_LEVEL);
        }
        Events.logEvent(state, $"{Js.Str(s.name)} has grown up (good at {Js.Str(a)} and {Js.Str(b)})");
    }
}
